insert into "fund_detail" ("path", "hs_name", "ticker", "fund_name", "fund_type", "ai_summary", "content") values (NULL, NULL, 'ES-GQG-UH', 'Wellington Global Quality Growth Fund', 'Mutual Fund', '<p><span>ES-GQG-UH ลงทุนในหุ้นเติบโตคุณภาพสูงทั่วโลกผ่านกองทุนหลัก Wellington Global Quality Growth Fund โดยเน้นคัดเลือกบริษัทที่มีสมดุลระหว่างการเติบโต มูลค่าพื้นฐาน ผลตอบแทนต่อเงินทุน และคุณภาพธุรกิจ กองทุนหลักมีประวัติชนะ MSCI ACWI ได้อย่างสม่ำเสมอ เหมาะกับนักลงทุนที่ต้องการ exposure หุ้นโลกแบบ active ที่เน้นการเลือกหุ้นรายตัวจากคุณภาพและโอกาสเติบโตระยะยาว</span></p>', '<h3><span>Wellington Global Quality Growth — หุ้นโลกคุณภาพสูง เอาชนะ MSCI ACWI ได้อย่างสม่ำเสมอ</span></h3> <p><span>ในสัปดาห์ที่ 17–21 สิงหาคม 2569 กองทุน ES-GQG-UH ยังคงอยู่ในพอร์ต Core โดยกองทุนหลัก Wellington Global Quality Growth Fund มีจุดแข็งในการคัดเลือกหุ้นรายตัวจากคุณภาพของบริษัท กระแสเงินสด ความสามารถในการแข่งขัน และโอกาสเติบโตระยะยาว เทียบกับดัชนี MSCI ACWI ข้อมูล ณ วันที่ 31 กรกฎาคม 2569</span></p> <p>&nbsp;</p> <h3><span>จุดเด่นกองทุน</span></h3> <ul> <li><span>ลงทุนในหุ้นเติบโตคุณภาพสูงทั่วโลกผ่านกองทุนหลัก Wellington Global Quality Growth Fund โดยเน้นคัดเลือกบริษัทที่มีสมดุลระหว่าง การเติบโต มูลค่าพื้นฐาน ผลตอบแทนต่อเงินทุน และคุณภาพของธุรกิจ เทียบกับดัชนี MSCI ACWI ทำให้นักลงทุนได้รับ exposure ต่อหุ้นผู้นำระดับโลกที่มีความสามารถในการทำกำไรและโครงสร้างธุรกิจแข็งแรง</span></li> <li><span>พอร์ตของกองทุนมีลักษณะกระจายตัวทั่วโลก แต่ยังให้น้ำหนักสูงกับตลาดสหรัฐฯ และกลุ่มเทคโนโลยี ทำให้เหมาะกับนักลงทุนที่ต้องการลงทุนในหุ้นโลกแบบ active โดยไม่ได้พึ่งพาเพียงธีมใดธีมหนึ่ง แต่เน้นการเลือกหุ้นรายตัวจากคุณภาพของบริษัท กระแสเงินสด ความสามารถในการแข่งขัน และโอกาสเติบโตระยะยาวของแต่ละธุรกิจ</span></li> <li><span>กองทุนหลักสามารถชนะ MSCI ACWI ได้อย่างสม่ำเสมอ</span></li> </ul> <p>&nbsp;</p> <p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/2026-08-17/images/page_044.png" width=''1282'' height=''890'' loading=''lazy'' alt=''ES-GQG-UH Core Portfolio Holdings and Per