padding: 4px;''><span>Apple</span></td> <td style=''padding: 4px;''><span>Consumer Electronics</span></td> <td style=''padding: 4px; text-align: right;''><span>2.7%</span></td> </tr> <tr> <td style=''padding: 4px;''><span>Microsoft</span></td> <td style=''padding: 4px;''><span>Software</span></td> <td style=''padding: 4px; text-align: right;''><span>2.5%</span></td> </tr> <tr> <td style=''padding: 4px;''><span>Broadcom</span></td> <td style=''padding: 4px;''><span>Semiconductors</span></td> <td style=''padding: 4px; text-align: right;''><span>2.5%</span></td> </tr> <tr> <td style=''padding: 4px;''><span>Amazon</span></td> <td style=''padding: 4px;''><span>Internet Retail</span></td> <td style=''padding: 4px; text-align: right;''><span>2.3%</span></td> </tr> <tr> <td style=''padding: 4px;''><span>Eli Lilly</span></td> <td style=''padding: 4px;''><span>Pharmaceutical</span></td> <td style=''padding: 4px; text-align: right;''><span>2.2%</span></td> </tr> <tr> <td style=''padding: 4px;''><span>Welltower</span></td> <td style=''padding: 4px;''><span>Healthcare REITs</span></td> <td style=''padding: 4px; text-align: right;''><span>2.2%</span></td> </tr> </tbody> </table> </div> <p>&nbsp;</p> <div data-hs-responsive-table=''true'' style=''overflow-x: auto; overflow-y: auto; max-height: 520px; max-width: 100%; width: 100%; margin-left: auto; margin-right: auto;''> <table style=''width: 100%; border-collapse: collapse; table-layout: fixed; border: 1px solid #99acc2;''> <tbody> <tr> <td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>Sector</span></td> <td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>Fund</span></td> <td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>ACWI</span></td> </tr> <tr> <td style=''padding: 4px;''><span>Technology</span></td> <td style=''padding: 4px; text-align: right;''><span>34.7%</