insert into "fund_detail" ("path", "hs_name", "ticker", "fund_name", "fund_type", "ai_summary", "content") values (NULL, NULL, 'DAOL-VOLT', 'DAOL-VOLT (ลงทุนผ่านกองทุนหลัก Tema Electrification ETF — VOLT)', 'Mutual Fund', '<p><span>DAOL-VOLT ลงทุนในธีม Electrification ผ่านกองทุนหลัก VOLT ETF ครอบคลุมห่วงโซ่ที่กว้างตั้งแต่การผลิตไฟฟ้า โครงสร้างพื้นฐาน ไปจนถึงอุปกรณ์ปลายทาง เหมาะสำหรับนักลงทุนที่ต้องการ exposure ต่อธีมความต้องการไฟฟ้าที่เร่งขึ้นทั่วโลก</span></p>', '<h3><span>DAOL-VOLT — ธีม Electrification ครอบคลุมห่วงโซ่ความต้องการไฟฟ้าทั้งระบบ</span></h3> <p><span>กองทุน DAOL-VOLT เป็น Satellite Portfolio ที่มุ่งเน้น exposure ต่อ power demand surge หรือการเร่งตัวของความต้องการใช้ไฟฟ้าโดยตรง โดยลงทุนผ่านกองทุนหลัก Tema Electrification ETF (VOLT) ซึ่งมีหุ้นในพอร์ตประมาณ 28 ตัว ในสัปดาห์ที่ 17–21 สิงหาคม 2569 กองทุนนี้ยังคงอยู่ในพอร์ตแนะนำระยะ 12 เดือน</span></p> <p>&nbsp;</p> <h3><span>จุดเด่นกองทุน</span></h3> <ul> <li><span>ลงทุนในธีม Electrification ผ่านกองทุนหลัก Tema Electrification ETF (VOLT) ซึ่งมีหุ้นในพอร์ตประมาณ 28 ตัว โดยจุดเด่นคือเน้นบริษัทที่ได้ประโยชน์จากความต้องการใช้ไฟฟ้าที่เพิ่มขึ้นทั่วโลก ทั้งจาก AI Data Center, EV, Digital Assets, การขยายกำลังผลิตไฟฟ้า และการลงทุนในโครงสร้างพื้นฐานพลังงาน ทำให้กองทุนเชื่อมโยงกับธีม power demand surge หรือการเร่งขึ้นของความต้องการไฟฟ้าโดยตรง</span></li> <li><span>จุดที่แตกต่างจาก GRID ETF คือ VOLT ไม่ได้เน้นเฉพาะการอัปเกรดโครงข่ายไฟฟ้าและ smart grid เป็นหลัก แต่ครอบคลุมห่วงโซ่ที่กว้างกว่า ตั้งแต่การผลิตไฟฟ้า การเพิ่มกำลังรองรับโหลดไฟฟ้า โครงสร้างพื้นฐานพลังงาน ไปจนถึงอุปกรณ์ที่เกี่ยวข้องกับการใช้ไฟฟ้าในระบบเศรษฐกิจยุคใหม่ จึงเหมาะกับนักลงทุนที่ต้องการ exposure ต่อธีมไฟฟ้าขาดแคลนและการเร่งลงทุนเพิ่ม capacity มากกว่าการลงทุนเฉพาะธีม grid modernization เพียงอย่างเดียว</span></li> </ul> <p>&nbsp;</p> <p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/2026-08-17/images/page_050.png" width=''1282'' height=''890'' loading=''lazy'' alt=''DAOL-VOLT Electrification ETF Holdings and Allocation'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p> <p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: DAOL-VOLT Electrification ETF Holdings and Allocation</span></p> <p>&nbsp;</p> <h3><span>การกระจายการลงทุน</span></h3> <p><span>ตารางด้านล่างแสดง Top Holdings การกระจายตามประเทศ และการกระจายตาม Power Sector ของกองทุนหลัก VOLT (ข้อมูลประเทศและ Top Holdings ณ วันที่ 31 กรกฎาคม 2569; Power Sector ณ วันที่ 30 มิถุนายน 2569)</span></p> <div data-hs-responsive-table=''true'' style=''overflow-x: auto; overflow-y: auto; max-height: 520px; max-width: 100%; width: 100%; margin-left: auto; margin-right: auto;''> <table style=''width: 100%; border-collapse: collapse; table-layout: fixed; border: 1px solid #99acc2;''> <tbody> <tr> <td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>Country</span></td> <td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>สัดส่วน</span></td> </tr> <tr><td style=''padding: 4px;''><span>U.S.</span></td><td style=''padding: 4px; text-align: right;''><span>81.48%</span></td></tr> <tr><td style=''padding: 4px;''><span>Ireland</span></td><td style=''padding: 4px; text-align: right;''><span>10.51%</span></td></tr> <tr><td style=''padding: 4px;''><span>Switzerland</span></td><td style=''padding: 4px; text-align: right;''><span>2.96%</span></td></tr> <tr><td style=''padding: 4px;''><span>France</span></td><td style=''padding: 4px; text-align: right;''><span>1.41%</span></td></tr> <tr><td style=''padding: 4px;''><span>Others</span></td><td style=''padding: 4px; text-align: right;''><span>3.64%</span></td></tr> </tbody> </table> </div> <p>&nbsp;</p> <div data-hs-responsive-table=''true'' style=''overflow-x: auto; overflow-y: auto; max-height: 520px; max-width: 100%; width: 100%; margin-left: auto; margin-right: auto;''> <table style=''width: 1